PRAGMA foreign_keys=ON;
CREATE TABLE student (student_id TEXT NOT NULL, name TEXT NOT NULL, date_of_birth TEXT NOT NULL, phone_number TEXT NOT NULL, home_address TEXT NOT NULL, registration_eligibility TEXT NOT NULL CHECK(registration_eligibility IN ('ELIGIBLE','INELIGIBLE')), class TEXT NOT NULL, major TEXT NOT NULL, PRIMARY KEY (student_id));
CREATE TABLE course (course_id TEXT NOT NULL, course_name TEXT NOT NULL, credits INTEGER NOT NULL CHECK(credits > 0), instructor TEXT NOT NULL, class_time TEXT NOT NULL, class_location TEXT NOT NULL, PRIMARY KEY (course_id));
CREATE TABLE registration (student_id TEXT NOT NULL, course_id TEXT NOT NULL, registration_time TEXT NOT NULL, status TEXT NOT NULL CHECK(status='REGISTERED'), registration_requested_at TEXT, registration_approved_at TEXT, course_started_at TEXT, course_assessment_completed_at TEXT, course_grade_finalized_at TEXT, PRIMARY KEY (student_id,course_id), FOREIGN KEY (student_id) REFERENCES student(student_id), FOREIGN KEY (course_id) REFERENCES course(course_id));
CREATE TABLE degree_examination_result (result_id TEXT NOT NULL, student_id TEXT NOT NULL, examination_name TEXT NOT NULL, grade INTEGER NOT NULL CHECK(grade BETWEEN 0 AND 100), examination_date TEXT NOT NULL, examination_scheduled_at TEXT, examination_checked_in_at TEXT, examination_score_published_at TEXT, examination_result_reviewed_at TEXT, PRIMARY KEY (result_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE task (task_id TEXT NOT NULL, task_title TEXT NOT NULL, task_description TEXT NOT NULL, task_start_date TEXT NOT NULL, task_end_date TEXT NOT NULL, task_location TEXT NOT NULL, PRIMARY KEY (task_id));
CREATE TABLE simulation_module (module_id TEXT NOT NULL, module_name TEXT NOT NULL, module_type TEXT NOT NULL, module_description TEXT NOT NULL, module_code TEXT NOT NULL, PRIMARY KEY (module_id));
CREATE TABLE thesis (thesis_id TEXT NOT NULL, student_id TEXT NOT NULL, thesis_title TEXT NOT NULL, thesis_content TEXT NOT NULL, submission_date TEXT NOT NULL, thesis_draft_registered_at TEXT, thesis_review_started_at TEXT, thesis_accepted_at TEXT, PRIMARY KEY (thesis_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE student_simulation_experiment_result (student_id TEXT NOT NULL, module_id TEXT NOT NULL, simulation_date TEXT NOT NULL, simulation_result_data TEXT NOT NULL, result_analysis TEXT NOT NULL, PRIMARY KEY (student_id,module_id,simulation_date), FOREIGN KEY (student_id) REFERENCES student(student_id), FOREIGN KEY (module_id) REFERENCES simulation_module(module_id));
CREATE TABLE assignment (assignment_id TEXT NOT NULL, student_id TEXT NOT NULL, assignment_content TEXT NOT NULL, assignment_assigned_at TEXT, assignment_submitted_at TEXT, assignment_grade_finalized_at TEXT, PRIMARY KEY (assignment_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE instructor (instructor_id TEXT NOT NULL, instructor_name TEXT NOT NULL, course TEXT NOT NULL, PRIMARY KEY (instructor_id));
CREATE TABLE assignment_grading (assignment_id TEXT NOT NULL, instructor_id TEXT NOT NULL, grading_time TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), evaluation TEXT NOT NULL, PRIMARY KEY (assignment_id,instructor_id,grading_time), FOREIGN KEY (assignment_id) REFERENCES assignment(assignment_id), FOREIGN KEY (instructor_id) REFERENCES instructor(instructor_id));
CREATE TABLE assignment_activity (event_id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (assignment_id) REFERENCES assignment(assignment_id));
CREATE TABLE simulation_module_activity (event_id TEXT PRIMARY KEY, module_id TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (module_id) REFERENCES simulation_module(module_id));
CREATE TABLE student_simulation_experiment_result_activity (event_id TEXT PRIMARY KEY, student_id TEXT NOT NULL, module_id TEXT NOT NULL, simulation_date TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (student_id,module_id,simulation_date) REFERENCES student_simulation_experiment_result(student_id,module_id,simulation_date));
CREATE TABLE thesis_activity (event_id TEXT PRIMARY KEY, thesis_id TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (thesis_id) REFERENCES thesis(thesis_id));
CREATE TABLE course_activity (event_id TEXT PRIMARY KEY, course_id TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (course_id) REFERENCES course(course_id));
CREATE TABLE task_activity (event_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, activity TEXT NOT NULL, occurred_at TEXT NOT NULL, outcome TEXT NOT NULL, FOREIGN KEY (task_id) REFERENCES task(task_id));
CREATE TABLE lifecycle_case_link(event_id TEXT NOT NULL,case_table TEXT NOT NULL,case_id TEXT NOT NULL,PRIMARY KEY(event_id,case_table,case_id));
